{
  "name": "@leon135/opencode-go-usage",
  "version": "0.1.3",
  "description": "OpenCode V2 TUI plugin showing opencode-go (Zen) usage limits in the sidebar and prompt footer",
  "type": "module",
  "author": "leon135",
  "license": "MIT",
  "main": "./dist/index.js",
  "repository": {
    "type": "git",
    "url": "https://github.com/leon135/opencode-go-usage.git"
  },
  "bugs": {
    "url": "https://github.com/leon135/opencode-go-usage/issues"
  },
  "homepage": "https://github.com/leon135/opencode-go-usage#readme",
  "publishConfig": {
    "access": "public"
  },
  "exports": {
    ".": "./dist/index.js",
    "./server": "./dist/index.js",
    "./tui": "./dist/tui.js"
  },
  "files": [
    "dist"
  ],
  "scripts": {
    "build": "bun run build.ts",
    "prepublishOnly": "bun run build.ts",
    "test": "bun test",
    "typecheck": "tsc --noEmit"
  },
  "dependencies": {
    "@opencode/plugin": "2.0.12"
  },
  "devDependencies": {
    "@opencode/theme": "2.0.12",
    "@opentui/core": "^0.5.8",
    "@opentui/solid": "0.5.12",
    "@types/node": "^24",
    "solid-js": "^1.9.0",
    "typescript": "^5.8.2"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.5.8",
    "@opentui/solid": ">=0.5.8",
    "solid-js": ">=1.9.0"
  }
}
